#include "core/trace_linking.hpp"
#include "core/session.hpp"
#include <iostream>
#include <random>
#include <sstream>
#include <stdexcept>
using namespace kleiotide;
void need(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(){try{std::mt19937 rng(421);std::string calls;for(int i=0;i<300;++i)calls+="ACGT"[rng()%4];auto original=std::make_shared<Chromatogram>();original->calls=calls;for(std::size_t i=0;i<calls.size();++i){original->peaks.push_back(i*5);original->quality.push_back(35);for(auto& channel:original->channels)for(int j=0;j<5;++j)channel.push_back(j);}
 auto exact=map_trace(calls,original);need(exact.link&&exact.orientation=="Forward"&&exact.quality=="Perfect","Exact forward mapping");for(int i=0;i<300;++i)need(exact.link->originalCalls[i]==i,"Exact original indices");
 auto trimmed=map_trace(calls.substr(30,220),original);need(trimmed.link&&trimmed.link->originalCalls.front()==30&&trimmed.link->originalCalls.back()==249,"Terminal trimming");
 std::string rev=calls;std::reverse(rev.begin(),rev.end());for(auto& c:rev)c=trace_complement(c);auto reversed=map_trace(rev,original);need(reversed.link&&reversed.link->reversed&&reversed.link->originalCalls.front()==299&&reversed.link->originalCalls.back()==0,"Reverse original indices");
 auto poor=std::make_shared<Chromatogram>(*original);poor->calls=std::string(80,'N')+calls+std::string(50,'N');for(int i=20;i<270;i+=3)poor->calls[80+i]='N';poor->quality.assign(poor->calls.size(),1);
 auto trimmedPoor=poor->calls.substr(90,280);auto poorMapping=map_trace(trimmedPoor,poor);need(poorMapping.link&&poorMapping.quality=="Perfect"&&poorMapping.link->originalCalls.front()==90&&poorMapping.link->originalCalls.back()==369,"Unique trimmed N-rich calls map perfectly regardless of peak quality");
 auto reversePoor=trimmedPoor;std::reverse(reversePoor.begin(),reversePoor.end());for(auto& c:reversePoor)c=trace_complement(c);auto poorReverse=map_trace(reversePoor,poor);need(poorReverse.link&&poorReverse.quality=="Perfect"&&poorReverse.link->originalCalls.front()==369,"Reverse trimmed N-rich exact indices");
 auto changed=calls.substr(20,260);changed[40]=changed[40]=='A'?'C':'A';changed.insert(100,"A");changed.erase(160,2);auto edited=map_trace(changed,original);need(edited.link&&edited.quality=="Good","Substitution and internal indels map");need(edited.link->originalCalls[100]==-1&&edited.link->originalCalls[110]==129,"Inserted/ambiguous bases have no invented peak; later mapping is stable");
 auto flanked=map_trace(std::string(30000,'N')+calls+std::string(200,'N'),original);need(flanked.link&&flanked.link->originalCalls[30000]==0&&flanked.link->originalCalls[29999]==-1,"Seeded long terminal additions");
 auto run=std::make_shared<Chromatogram>();run->calls=calls.substr(0,100)+"AAAAAA"+calls.substr(100);auto runQuery=run->calls;runQuery.erase(102,1);auto uncertain=map_trace(runQuery,run);need(uncertain.link&&uncertain.link->originalCalls[90]==90&&uncertain.link->originalCalls[140]==141,"Homopolymer deletion leaves flanking peaks aligned");std::size_t missing=0;for(int i=100;i<105;++i)missing+=uncertain.link->originalCalls[i]<0;need(missing>=4,"Equally optimal homopolymer positions remain unmapped");
 auto repeated=map_trace(calls+std::string(50,'N')+calls,original);need(!repeated.link,"Repeated placements fail");auto pal=std::make_shared<Chromatogram>();pal->calls="ACGTACGTACGTACGT";need(!map_trace(pal->calls,pal).link,"Ambiguous orientation fails");need(!map_trace(std::string(100,'N'),original).link,"Missing calls cannot establish mapping");
 bool cancelled=false;try{map_trace(calls,original,[]{return true;});}catch(const std::exception&){cancelled=true;}need(cancelled,"Cancellation");
 need(suggest_trace("sample",{"sample","other"},{"x","y"})==0,"Exact file match");need(suggest_trace("sample",{"sample_a","sample_b"},{"sample","x"})==-1,"Ambiguous earlier tier stays unassigned");need(suggest_trace("internal",{"fileAAA","fileBBB"},{"x","internal"})==1,"Internal exact match");
 Document d;d.load({{"a",calls},{"b",rev}});const auto state=d.state_id();bool refused=false;try{apply_trace_links(d,{{1,exact.link},{999,reversed.link}});}catch(...){refused=true;}need(refused&&d.state_id()==state&&!d.sequence(1).trace,"Invalid batch leaves all rows unchanged");apply_trace_links(d,{{1,exact.link},{2,reversed.link}});need(d.sequence(1).trace&&d.sequence(2).trace&&d.sequence(1).symbols.text()==calls,"Atomic links preserve symbols");d.undo();need(d.state_id()==state&&!d.sequence(1).trace&&!d.sequence(2).trace,"One Undo unlinks all");d.redo();apply_trace_links(d,{{1,{}}});need(!d.sequence(1).trace&&d.sequence(2).trace,"Unlink only association");d.undo();need(d.sequence(1).trace==exact.link,"Undo restores original link");std::ostringstream out;write_session(out,d);std::istringstream in(out.str());auto session=read_session(in);need(session.document.sequence(1).trace->original==session.document.sequence(2).trace->original,"Session deduplicates shared original evidence");need(session.document.sequence(2).trace->reversed,"Orientation persists");
 std::cout<<"PASS trace mapping: forward/reverse ground truth, trims/large additions, substitutions/indels, ambiguous repeats/orientation, cancellation, name tiers, shared evidence, atomic Undo/Redo and session persistence\n";
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
